","partOfSpeech":"noun phrase","translationUz":"keskin xulosa","definitionEn":"a far-reaching interpretation"},{"testNo":6,"passageNo":3,"surface":"contradicts","partOfSpeech":"verb","translationUz":"zid keladi","definitionEn":"conflicts with established claims"},{"testNo":6,"passageNo":3,"surface":"political and managerial theory","partOfSpeech":"noun phrase","translationUz":"siyosiy va boshqaruv nazariyasi","definitionEn":"the established explanation of political and managerial decision making"},{"testNo":6,"passageNo":3,"surface":"doubtless","partOfSpeech":"adverb","translationUz":"shubhasiz","definitionEn":"without doubt"},{"testNo":6,"passageNo":3,"surface":"comforts","partOfSpeech":"verb","translationUz":"ko‘ngliga xush yoqadi","definitionEn":"provides reassurance"},{"testNo":6,"passageNo":3,"surface":"attractive proposition","partOfSpeech":"noun phrase","translationUz":"jozibali taklif","definitionEn":"an appealing suggested approach"},{"testNo":6,"passageNo":3,"surface":"suspects","partOfSpeech":"verb","translationUz":"taxmin qiladi","definitionEn":"believes something may be true"},{"testNo":6,"passageNo":3,"surface":"embrace","partOfSpeech":"verb","translationUz":"o‘zlashtirib olmoq","definitionEn":"accept an approach"},{"testNo":6,"passageNo":3,"surface":"wisdom","partOfSpeech":"noun","translationUz":"donishmandlik","definitionEn":"practical understanding"},{"testNo":6,"passageNo":3,"surface":"realms","partOfSpeech":"noun","translationUz":"sohalar","definitionEn":"areas of activity"},{"testNo":6,"passageNo":3,"surface":"society","partOfSpeech":"noun","translationUz":"jamiyat","definitionEn":"a community of people"},{"testNo":6,"passageNo":3,"surface":"governance","partOfSpeech":"noun","translationUz":"boshqaruv","definitionEn":"the process of governing"},{"testNo":6,"passageNo":3,"surface":"problematic implications","partOfSpeech":"noun phrase","translationUz":"bahsli oqibatlar","definitionEn":"consequences that raise difficulties"},{"testNo":6,"passageNo":3,"surface":"surface","partOfSpeech":"verb","translationUz":"ko‘zga tashlanmoq","definitionEn":"become apparent"},{"testNo":6,"passageNo":3,"surface":"variables","partOfSpeech":"noun","translationUz":"omillar","definitionEn":"factors that may change"},{"testNo":6,"passageNo":3,"surface":"neatly circumscribed","partOfSpeech":"adjective phrase","translationUz":"aniq chegaralangan","definitionEn":"clearly defined within boundaries"},{"testNo":6,"passageNo":3,"surface":"clarity","partOfSpeech":"noun","translationUz":"ravshanlik","definitionEn":"the state of being clear"},{"testNo":6,"passageNo":3,"surface":"group dynamics","partOfSpeech":"noun phrase","translationUz":"guruh dinamikasi","definitionEn":"patterns of interaction within groups"},{"testNo":6,"passageNo":3,"surface":"social interaction","partOfSpeech":"noun phrase","translationUz":"ijtimoiy munosabatlar","definitionEn":"communication and behaviour between people"},{"testNo":6,"passageNo":3,"surface":"pertinent","partOfSpeech":"adjective","translationUz":"o‘rinli","definitionEn":"directly relevant"},{"testNo":6,"passageNo":3,"surface":"arise","partOfSpeech":"verb","translationUz":"paydo bo‘lmoq","definitionEn":"become apparent"},{"testNo":6,"passageNo":3,"surface":"counts as","partOfSpeech":"phrasal verb","translationUz":"deb hisoblanadi","definitionEn":"qualifies as something"},{"testNo":6,"passageNo":3,"surface":"outcome","partOfSpeech":"noun","translationUz":"natija","definitionEn":"the final result"},{"testNo":6,"passageNo":3,"surface":"social psychologist","partOfSpeech":"noun phrase","translationUz":"ijtimoiy psixolog","definitionEn":"a psychologist who studies social behaviour"},{"testNo":6,"passageNo":3,"surface":"respects","partOfSpeech":"verb","translationUz":"hurmat qiladi","definitionEn":"regards as legitimate"},{"testNo":6,"passageNo":3,"surface":"classic studies","partOfSpeech":"noun phrase","translationUz":"klassik tadqiqotlar","definitionEn":"well-established influential research"},{"testNo":6,"passageNo":3,"surface":"participating","partOfSpeech":"verb","translationUz":"ishtirok etish","definitionEn":"taking part in a process"},{"testNo":6,"passageNo":3,"surface":"abide by","partOfSpeech":"phrasal verb","translationUz":"rioya qilmoq","definitionEn":"follow accepted rules or outcomes"},{"testNo":6,"passageNo":3,"surface":"results","partOfSpeech":"noun","translationUz":"natijalar","definitionEn":"outcomes of a process"},{"testNo":6,"passageNo":3,"surface":"decision-makers","partOfSpeech":"noun","translationUz":"qaror qabul qiluvchilar","definitionEn":"people responsible for making decisions"},{"testNo":6,"passageNo":3,"surface":"at fault","partOfSpeech":"phrase","translationUz":"aybdor","definitionEn":"responsible for a mistake"},{"testNo":6,"passageNo":3,"surface":"invaluable","partOfSpeech":"adjective","translationUz":"beqiyos ahamiyatli","definitionEn":"extremely valuable"},{"testNo":6,"passageNo":3,"surface":"limitations","partOfSpeech":"noun","translationUz":"cheklovlar","definitionEn":"restrictions in what can be achieved"},{"testNo":6,"passageNo":3,"surface":"conventional wisdom","partOfSpeech":"noun phrase","translationUz":"umumiy qabul qilingan qarash","definitionEn":"a commonly accepted belief"},{"testNo":6,"passageNo":3,"surface":"decision quality","partOfSpeech":"noun phrase","translationUz":"qaror sifati","definitionEn":"how good the outcome of a decision is"},{"testNo":6,"passageNo":3,"surface":"rises","partOfSpeech":"verb","translationUz":"oshadi","definitionEn":"increases"},{"testNo":6,"passageNo":3,"surface":"tempts","partOfSpeech":"verb","translationUz":"xomxayolga yetaklaydi","definitionEn":"encourages someone to believe an oversimplification"},{"testNo":6,"passageNo":3,"surface":"ideology","partOfSpeech":"noun","translationUz":"mafkura","definitionEn":"a system of political or social beliefs"},{"testNo":6,"passageNo":3,"surface":"group membership","partOfSpeech":"noun phrase","translationUz":"guruhga mansublik","definitionEn":"belonging to a group"},{"testNo":6,"passageNo":3,"surface":"social considerations","partOfSpeech":"noun phrase","translationUz":"ijtimoiy omillar","definitionEn":"social factors relevant to an issue"},{"testNo":6,"passageNo":3,"surface":"general appeal","partOfSpeech":"noun phrase","translationUz":"umumiy jozibadorlik","definitionEn":"a quality that attracts broad support"}],"corrections":[],"offsetRepairs":[{"testNo":6,"passageNo":2,"id":"8a6b5855-66ce-4c1e-b431-e4fa48b2a2b1","surface":"cop-out","expectedStart":123,"matchOrdinal":1},{"testNo":6,"passageNo":2,"id":"7b7905a4-8261-44e1-9dce-e056baa16aa9","surface":"fossil fuel","expectedStart":871,"matchOrdinal":1},{"testNo":6,"passageNo":3,"id":"479348a3-ae07-4eb5-b051-3293653a84dd","surface":"deliberation","expectedStart":104,"matchOrdinal":2},{"testNo":6,"passageNo":3,"id":"208d5380-58ce-46c0-b94e-30271e7f7828","surface":"Deliberation","expectedStart":111,"matchOrdinal":3},{"testNo":6,"passageNo":3,"id":"73bc72d4-c80c-40e0-80bf-1e0e6d9ff6eb","surface":"snap' decisions","expectedStart":208,"matchOrdinal":1},{"testNo":6,"passageNo":3,"id":"ef7b5149-4d7a-4e45-9c0c-781dc4784836","surface":"group-think","expectedStart":378,"matchOrdinal":1},{"testNo":6,"passageNo":3,"id":"519e1ff7-e9e4-43c2-9b2a-16d0ac63a192","surface":"deliberation","expectedStart":613,"matchOrdinal":7}]}$plan$::jsonb;
  v_check record;
  v_repair record;
  v_item record;
  v_old record;
  v_passage_id uuid;
  v_body text;
  v_word text;
  v_part text;
  v_lexical_type text;
  v_unit_id uuid;
  v_lexeme_id uuid;
  v_sense_key text;
  v_regex text;
  v_start integer;
  v_total integer;
  v_ordinal integer;
  v_rows integer;
  v_repaired integer := 0;
  v_corrected integer := 0;
  v_inserted integer := 0;
BEGIN
  PERFORM pg_advisory_xact_lock(11061401);

  -- Fail before any mutation if any source text or catalogue slot changed.
  FOR v_check IN SELECT key, value FROM jsonb_each_text(v_plan->'passages') LOOP
    SELECT COUNT(*), MIN(body_text) INTO v_total, v_body
      FROM reading_passages
      WHERE test_no=split_part(v_check.key,'-',1)::integer
        AND passage_no=split_part(v_check.key,'-',2)::integer;
    IF v_total <> 1 OR v_body IS NULL
       OR encode(extensions.digest(v_body,'sha256'),'hex') <> v_check.value THEN
      RAISE EXCEPTION 'Reading source checksum mismatch: %', v_check.key;
    END IF;
  END LOOP;

  -- Repair exact incorrect spans in passages 002 and 003 without changing IDs.
  FOR v_repair IN
    SELECT * FROM jsonb_to_recordset(v_plan->'offsetRepairs')
      AS r("testNo" integer,"passageNo" integer,id text,surface text,
           "expectedStart" integer,"matchOrdinal" integer)
  LOOP
    SELECT p.id,p.body_text,o.start_char,o.end_char,o.surface_form
      INTO v_old
      FROM lexical_occurrences o
      JOIN reading_passages p ON p.id=o.passage_id
      WHERE o.id=v_repair.id::uuid
        AND p.test_no=v_repair."testNo"
        AND p.passage_no=v_repair."passageNo";
    IF NOT FOUND OR lower(v_old.surface_form) <> lower(v_repair.surface) THEN
      RAISE EXCEPTION 'Reading repair target changed: %',v_repair.id;
    END IF;
    v_regex:='(?i)(?<![[:alpha:]])'||v_repair.surface||'(?![[:alpha:]])';
    v_start:=regexp_instr(v_old.body_text,v_regex,1,v_repair."matchOrdinal")-1;
    IF v_start<0 OR lower(substr(v_old.body_text,v_start+1,length(v_repair.surface)))
       <> lower(v_repair.surface) THEN
      RAISE EXCEPTION 'Reading repair missing or mismatched surface: %',v_repair.id;
    END IF;
    IF v_old.start_char=v_start AND v_old.end_char=v_start+length(v_repair.surface) THEN
      CONTINUE;
    END IF;
    IF v_old.start_char<>v_repair."expectedStart"
       OR EXISTS(SELECT 1 FROM lexical_occurrences o
         WHERE o.passage_id=v_old.id AND o.id<>v_repair.id::uuid
           AND o.start_char<v_start+length(v_repair.surface) AND o.end_char>v_start) THEN
      RAISE EXCEPTION 'Reading repair conflicts with prior span: %',v_repair.id;
    END IF;
    UPDATE lexical_occurrences o
      SET start_char=v_start,end_char=v_start+length(v_repair.surface),
        sentence_text=substr(v_old.body_text,greatest(1,v_start-120),260)
      WHERE o.id=v_repair.id::uuid;
    v_repaired:=v_repaired+1;
  END LOOP;

  -- Correct polysemous meanings in 001-003 and enrich 007-009.
  FOR v_item IN
    SELECT x.kind,x.test_no,x.passage_no,x.surface,x.pos,x.uz,x.definition
    FROM (
      SELECT 'correction'::text AS kind,c."testNo" AS test_no,
        c."passageNo" AS passage_no,c.surface,c."partOfSpeech" AS pos,
        c."translationUz" AS uz,c."definitionEn" AS definition
        FROM jsonb_to_recordset(v_plan->'corrections')
        AS c("testNo" integer,"passageNo" integer,surface text,
             "partOfSpeech" text,"translationUz" text,"definitionEn" text)
      UNION ALL
      SELECT 'new'::text AS kind,t."testNo" AS test_no,
        t."passageNo" AS passage_no,t.surface,t."partOfSpeech" AS pos,
        t."translationUz" AS uz,t."definitionEn" AS definition
        FROM jsonb_to_recordset(v_plan->'terms')
        AS t("testNo" integer,"passageNo" integer,surface text,
             "partOfSpeech" text,"translationUz" text,"definitionEn" text)
    ) AS x
    ORDER BY CASE WHEN x.kind='correction' THEN 0 ELSE 1 END,
      LENGTH(x.surface) DESC,x.test_no,x.passage_no,x.surface
  LOOP
    SELECT id,body_text INTO v_passage_id,v_body FROM reading_passages
      WHERE test_no=v_item.test_no AND passage_no=v_item.passage_no;
    IF v_passage_id IS NULL THEN
      RAISE EXCEPTION 'Reading passage missing: %-%',v_item.test_no,v_item.passage_no;
    END IF;
    v_word:=lower(trim(regexp_replace(v_item.surface,'[[:space:]]+',' ','g')));
    v_part:=lower(trim(v_item.pos));
    v_regex:='(?i)(?<![[:alpha:]])'||v_item.surface||'(?![[:alpha:]])';
    v_total:=regexp_count(v_body,v_regex);
    IF v_total<1 THEN
      RAISE EXCEPTION 'Reading vocabulary surface absent: %-%, %',v_item.test_no,v_item.passage_no,v_item.surface;
    END IF;
    IF v_item.kind='correction' THEN
      SELECT COUNT(*) INTO v_rows FROM lexical_occurrences
        WHERE passage_id=v_passage_id AND lower(surface_form)=v_word;
      IF v_rows<1 THEN
        RAISE EXCEPTION 'Reading correction cardinality changed: %-%, %',v_item.test_no,v_item.passage_no,v_item.surface;
      END IF;
    END IF;
    v_lexical_type:=CASE v_part
      WHEN 'noun phrase' THEN 'noun_phrase'
      WHEN 'verb phrase' THEN 'verb_phrase'
      WHEN 'phrasal verb' THEN 'phrasal_verb'
      WHEN 'idiom' THEN 'idiom'
      WHEN 'collocation' THEN 'collocation'
      WHEN 'fixed expression' THEN 'fixed_expression'
      WHEN 'compound' THEN 'compound'
      WHEN 'phrase' THEN 'phrase'
      ELSE CASE WHEN position(' ' IN v_word)>0 THEN 'phrase' ELSE 'word' END
    END;
    -- Reuse a lexical unit of the same lemma, POS and lexical type.
    INSERT INTO lexical_units
      (language,lemma,lemma_norm,part_of_speech,lexical_type,
       is_function_word,provenance)
      VALUES('en',v_item.surface,v_word,v_part,v_lexical_type,false,
             'reading_context')
      ON CONFLICT(language,lemma_norm,part_of_speech,lexical_type) DO NOTHING;
    SELECT id INTO STRICT v_unit_id FROM lexical_units
      WHERE language='en' AND lemma_norm=v_word
        AND part_of_speech=v_part AND lexical_type=v_lexical_type;
    INSERT INTO lexical_unit_forms
      (lexical_unit_id,form,form_norm,form_type)
      VALUES(v_unit_id,v_item.surface,v_word,'lemma')
      ON CONFLICT(lexical_unit_id,form_norm) DO NOTHING;

    -- The v2 key is SHA256(JSON([normalised term, POS, English meaning])).
    v_sense_key:='v2:'||encode(extensions.digest(
      replace(json_build_array(v_word,v_part,lower(trim(v_item.definition)))::text,
              '", "', '","'),'sha256'),'hex');
    SELECT id INTO v_lexeme_id FROM lexemes
      WHERE sense_key=v_sense_key;
    IF v_lexeme_id IS NULL THEN
      -- Honor exact legacy senses too; do not duplicate identical meanings.
      SELECT id INTO v_lexeme_id FROM lexemes
        WHERE lower(trim(term))=v_word AND lower(trim(coalesce(part_of_speech,'')))=v_part
          AND lower(trim(definition_en))=lower(trim(v_item.definition))
        ORDER BY id LIMIT 1;
    END IF;
    IF v_lexeme_id IS NULL THEN
      INSERT INTO lexemes
        (term,part_of_speech,definition_en,translation_uz,example_sentence,
         lexical_unit_id,sense_key,provenance,verification_status,import_batch)
        VALUES(v_item.surface,v_item.pos,v_item.definition,v_item.uz,
               NULL,v_unit_id,v_sense_key,'reading_context',
               'context_checked','20261114-passages-016-018')
        ON CONFLICT(sense_key) DO NOTHING
        RETURNING id INTO v_lexeme_id;
      IF v_lexeme_id IS NULL THEN
        SELECT id INTO STRICT v_lexeme_id FROM lexemes WHERE sense_key=v_sense_key;
      END IF;
    END IF;
    SELECT coalesce(lexical_unit_id,v_unit_id) INTO v_unit_id
      FROM lexemes WHERE id=v_lexeme_id;

    IF v_item.kind='correction' THEN
      UPDATE lexical_occurrences
        SET lexeme_id=v_lexeme_id,lexical_unit_id=v_unit_id,
            resolution_status='resolved',resolution_source='context_editorial'
        WHERE passage_id=v_passage_id AND lower(surface_form)=v_word;
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      v_corrected:=v_corrected+v_rows;
      CONTINUE;
    END IF;

    FOR v_ordinal IN 1..v_total LOOP
      v_start:=regexp_instr(v_body,v_regex,1,v_ordinal)-1;
      IF v_start<0 OR lower(substr(v_body,v_start+1,length(v_item.surface)))
        <> lower(v_item.surface) THEN
        RAISE EXCEPTION 'Source text shifted while linking: %-%, %',v_item.test_no,v_item.passage_no,v_item.surface;
      END IF;
      -- Keep pre-existing curated multiword senses authoritative.
      IF EXISTS(SELECT 1 FROM lexical_occurrences o
          WHERE o.passage_id=v_passage_id
            AND o.start_char<v_start+length(v_item.surface)
            AND o.end_char>v_start) THEN
        CONTINUE;
      END IF;
      INSERT INTO lexical_occurrences
        (source_type,passage_id,start_char,end_char,surface_form,lexeme_id,
         lexical_unit_id,resolution_status,resolution_source,sentence_text,
         occurrence_type,is_target_vocabulary)
        VALUES('reading',v_passage_id,v_start,v_start+length(v_item.surface),
               substr(v_body,v_start+1,length(v_item.surface)),
               v_lexeme_id,v_unit_id,'resolved','context_editorial',
               substr(v_body,greatest(1,v_start-120),260),
               'vocabulary',true)
        ON CONFLICT(passage_id,start_char,end_char) DO NOTHING;
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      v_inserted:=v_inserted+v_rows;
    END LOOP;
  END LOOP;
  RAISE NOTICE 'reading contextual links: repaired %, corrected %, added %',
    v_repaired,v_corrected,v_inserted;
END
$executor$;
